def construir_arbol(rutas):
    arbol = {}
    for ruta in rutas:
        partes = ruta.split('/')
        nodo_actual = arbol
        for i, parte in enumerate(partes):
            if i == len(partes) - 1:
                # Es la última parte de la ruta, debe ser un diccionario vacío
                nodo_actual[parte] = {}
            else:
                # Si la clave no existe, crear diccionario; si existe, navegar
                if parte not in nodo_actual:
                    nodo_actual[parte] = {}
                nodo_actual = nodo_actual[parte]
    return arbol
