import csv
import io

def totales(texto_csv):
    resultado = {}
    # Usamos io.StringIO para que el módulo csv pueda leer el string como un archivo
    f = io.StringIO(texto_csv.strip())
    reader = csv.reader(f)

    try:
        # Intentar leer la cabecera
        header = next(reader, None)
    except StopIteration:
        return {}

    for row in reader:
        # Ignorar líneas vacías o que no tengan las 3 columnas
        if not row or len(row) < 3:
            continue

        producto = row[0].strip()
        if not producto:
            continue

        try:
            cantidad = float(row[1])
            precio = float(row[2])
            importe = cantidad * precio

            if producto in resultado:
                resultado[producto] += importe
            else:
                resultado[producto] = importe
        except ValueError:
            # Ignorar filas donde cantidad o precio no sean numéricos
            continue

    # Redondear a 2 decimales
    return {k: round(v, 2) for k, v in resultado.items()}
