def restar_intervalos(base, cortes):
    def merge_intervals(intervals):
        if not intervals:
            return []
        # Sort by start point
        sorted_intervals = sorted(intervals)
        merged = []
        curr_start, curr_end = sorted_intervals[0]
        for next_start, next_end in sorted_intervals[1:]:
            if next_start <= curr_end:
                curr_end = max(curr_end, next_end)
            else:
                merged.append((curr_start, curr_end))
                curr_start, curr_end = next_start, next_end
        merged.append((curr_start, curr_end))
        # Remove zero-length and merge adjacent
        final = []
        for s, e in merged:
            if s < e:
                if final and final[-1][1] == s:
                    final[-1] = (final[-1][0], e)
                else:
                    final.append((s, e))
        return final

    # Step 1: Merge base intervals
    merged_base = merge_intervals(base)
    # Step 2: Merge cut intervals
    merged_cuts = merge_intervals(cortes)

    result = []
    for b_start, b_end in merged_base:
        current_segments = [(b_start, b_end)]

        for c_start, c_end in merged_cuts:
            new_segments = []
            for s, e in current_segments:
                # If no overlap
                if c_end <= s or c_start >= e:
                    new_segments.append((s, e))
                else:
                    # Part before cut
                    if c_start > s:
                        new_segments.append((s, c_start))
                    # Part after cut
                    if c_end < e:
                        new_segments.append((c_end, e))
            current_segments = new_segments

        result.extend(current_segments)

    # Final pass to merge adjacent segments that might have been split 
    # or created by the subtraction logic
    final_result = []
    for s, e in result:
        if s < e:
            if final_result and final_result[-1][1] == s:
                final_result[-1] = (final_result[-1][0], e)
            else:
                final_result.append((s, e))

    return final_result
