import heapq

def orden_topologico(dependencias: dict[str, list[str]]) -> list[str]:
    # Identificar todas las tareas únicas (claves y dependencias)
    all_tasks = set(dependencias.keys())
    for deps in dependencias.values():
        for d in deps:
            all_tasks.add(d)

    # Construir el grafo de adyacencia (quién depende de quién)
    # y contar el grado de entrada (cuántas dependencias tiene cada tarea)
    adj = {task: [] for task in all_tasks}
    in_degree = {task: 0 for task in all_tasks}

    for task, deps in dependencias.items():
        # El diccionario original dice: task depende de cada d en deps
        # Por lo tanto, el flujo es d -> task
        in_degree[task] = len(set(deps))
        for d in set(deps):
            adj[d].append(task)

    # Algoritmo de Kahn con prioridad para orden alfabético
    # Las tareas con in_degree 0 son las que no tienen dependencias pendientes
    queue = [task for task in all_tasks if in_degree[task] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        u = heapq.heappop(queue)
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

    if len(result) != len(all_tasks):
        raise ValueError("Ciclo detectado en las dependencias")

    return result
```

